	Запрос.УстановитьПараметр("ТаблицаТоваров", Объект[ПараметрыУказанияСерий.ИмяТЧТовары].Выгрузить());

		Если ПараметрыУказанияСерий.ИмяПоляПомещение <> Неопределено Тогда
