		Возврат НСтр("ru = 'Целостные данные'");
	ИначеЕсли СтатусПроверки = "ЛишнийФайлВТоме" Тогда 
		Возврат НСтр("ru = 'Лишние файлы (есть на диске, но сведения о них отсутствуют)'");
	ИначеЕсли СтатусПроверки = "НетФайлаВТоме" Тогда
		Возврат НСтр("ru = 'Отсутствуют файлы в томе на диске'");
	КонецЕсли;
